import{_ as p,a0 as r,w as o,s as d,ao as l,I as t,x as a,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Linux 上如何得到一个段错误的核心转储 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上如何得到一个段错误的核心转储 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上如何得到一个段错误的核心转储 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上如何得到一个段错误的核心转储 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180428 How to get a core dump for a segfault on Linux","title":"在 Linux 上如何得到一个段错误的核心转储","tag":"201807","desc":""},"relativePath":"201807/20180428 How to get a core dump for a segfault on Linux.md","filePath":"[post].md"}'),c={name:"201807/20180428 How to get a core dump for a segfault on Linux.md"};function u(b,e,h,g,m,k){const s=r("Link");return o(),d("div",null,[e[20]||(e[20]=l(`<h1 id="在-linux-上如何得到一个段错误的核心转储" tabindex="-1">在 Linux 上如何得到一个段错误的核心转储 <a class="header-anchor" href="#在-linux-上如何得到一个段错误的核心转储" aria-label="Permalink to “在 Linux 上如何得到一个段错误的核心转储”">​</a></h1><p>本周工作中，我花了整整一周的时间来尝试调试一个段错误。我以前从来没有这样做过，我花了很长时间才弄清楚其中涉及的一些基本事情（获得核心转储、找到导致段错误的行号）。于是便有了这篇博客来解释如何做那些事情！</p><p>在看完这篇博客后，你应该知道如何从“哦，我的程序出现段错误，但我不知道正在发生什么”到“我知道它出现段错误时的堆栈、行号了！ “。</p><h3 id="什么是段错误" tabindex="-1">什么是段错误？ <a class="header-anchor" href="#什么是段错误" aria-label="Permalink to “什么是段错误？”">​</a></h3><p>“<ruby>段错误<rt>segmentation fault</rt></ruby>”是指你的程序尝试访问不允许访问的内存地址的情况。这可能是由于：</p><ul><li>试图解引用空指针（你不被允许访问内存地址 <code>0</code>）；</li><li>试图解引用其他一些不在你内存（LCTT 译注：指不在合法的内存地址区间内）中的指针；</li><li>一个已被破坏并且指向错误的地方的 <ruby>C++ 虚表指针<rt>C++ vtable pointer</rt></ruby>，这导致程序尝试执行没有执行权限的内存中的指令；</li><li>其他一些我不明白的事情，比如我认为访问未对齐的内存地址也可能会导致段错误（LCTT 译注：在要求自然边界对齐的体系结构，如 MIPS、ARM 中更容易因非对齐访问产生段错误）。</li></ul><p>这个“C++ 虚表指针”是我的程序发生段错误的情况。我可能会在未来的博客中解释这个，因为我最初并不知道任何关于 C++ 的知识，并且这种虚表查找导致程序段错误的情况也是我所不了解的。</p><p>但是！这篇博客后不是关于 C++ 问题的。让我们谈论的基本的东西，比如，我们如何得到一个核心转储？</p><h3 id="步骤1-运行-valgrind" tabindex="-1">步骤1：运行 valgrind <a class="header-anchor" href="#步骤1-运行-valgrind" aria-label="Permalink to “步骤1：运行 valgrind”">​</a></h3><p>我发现找出为什么我的程序出现段错误的最简单的方式是使用 <code>valgrind</code>：我运行</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>valgrind -v your-program</span></span></code></pre></div><p>这给了我一个故障时的堆栈调用序列。 简洁！</p><p>但我想也希望做一个更深入调查，并找出些 <code>valgrind</code> 没告诉我的信息！ 所以我想获得一个核心转储并探索它。</p><h3 id="如何获得一个核心转储" tabindex="-1">如何获得一个核心转储 <a class="header-anchor" href="#如何获得一个核心转储" aria-label="Permalink to “如何获得一个核心转储”">​</a></h3><p><ruby>核心转储<rt>core dump</rt></ruby>是您的程序内存的一个副本，并且当您试图调试您的有问题的程序哪里出错的时候它非常有用。</p><p>当您的程序出现段错误，Linux 的内核有时会把一个核心转储写到磁盘。 当我最初试图获得一个核心转储时，我很长一段时间非常沮丧，因为 - Linux 没有生成核心转储！我的核心转储在哪里？</p><p>这就是我最终做的事情：</p><ol><li>在启动我的程序之前运行 <code>ulimit -c unlimited</code></li><li>运行 <code>sudo sysctl -w kernel.core_pattern=/tmp/core-%e.%p.%h.%t</code></li></ol><h3 id="ulimit-设置核心转储的最大尺寸" tabindex="-1">ulimit：设置核心转储的最大尺寸 <a class="header-anchor" href="#ulimit-设置核心转储的最大尺寸" aria-label="Permalink to “ulimit：设置核心转储的最大尺寸”">​</a></h3><p><code>ulimit -c</code> 设置核心转储的最大尺寸。 它往往设置为 0，这意味着内核根本不会写核心转储。 它以千字节为单位。 <code>ulimit</code> 是按每个进程分别设置的 —— 你可以通过运行 <code>cat /proc/PID/limit</code> 看到一个进程的各种资源限制。</p><p>例如这些是我的系统上一个随便一个 Firefox 进程的资源限制：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/6309/limits </span></span>
<span class="line"><span>Limit                     Soft Limit           Hard Limit           Units     </span></span>
<span class="line"><span>Max cpu time              unlimited            unlimited            seconds   </span></span>
<span class="line"><span>Max file size             unlimited            unlimited            bytes     </span></span>
<span class="line"><span>Max data size             unlimited            unlimited            bytes     </span></span>
<span class="line"><span>Max stack size            8388608              unlimited            bytes     </span></span>
<span class="line"><span>Max core file size        0                    unlimited            bytes     </span></span>
<span class="line"><span>Max resident set          unlimited            unlimited            bytes     </span></span>
<span class="line"><span>Max processes             30571                30571                processes </span></span>
<span class="line"><span>Max open files            1024                 1048576              files     </span></span>
<span class="line"><span>Max locked memory         65536                65536                bytes     </span></span>
<span class="line"><span>Max address space         unlimited            unlimited            bytes     </span></span>
<span class="line"><span>Max file locks            unlimited            unlimited            locks     </span></span>
<span class="line"><span>Max pending signals       30571                30571                signals   </span></span>
<span class="line"><span>Max msgqueue size         819200               819200               bytes     </span></span>
<span class="line"><span>Max nice priority         0                    0                    </span></span>
<span class="line"><span>Max realtime priority     0                    0                    </span></span>
<span class="line"><span>Max realtime timeout      unlimited            unlimited            us</span></span></code></pre></div><p>内核在决定写入多大的核心转储文件时使用<ruby>软限制<rt>soft limit</rt></ruby>（在这种情况下，<code>max core file size = 0</code>）。 您可以使用 shell 内置命令 <code>ulimit</code>（<code>ulimit -c unlimited</code>） 将软限制增加到<ruby>硬限制<rt>hard limit</rt></ruby>。</p><h3 id="kernel-core-pattern-核心转储保存在哪里" tabindex="-1">kernel.core_pattern：核心转储保存在哪里 <a class="header-anchor" href="#kernel-core-pattern-核心转储保存在哪里" aria-label="Permalink to “kernel.core_pattern：核心转储保存在哪里”">​</a></h3><p><code>kernel.core_pattern</code> 是一个内核参数，或者叫 “sysctl 设置”，它控制 Linux 内核将核心转储文件写到磁盘的哪里。</p><p>内核参数是一种设定您的系统全局设置的方法。您可以通过运行 <code>sysctl -a</code> 得到一个包含每个内核参数的列表，或使用 <code>sysctl kernel.core_pattern</code> 来专门查看 <code>kernel.core_pattern</code> 设置。</p><p>所以 <code>sysctl -w kernel.core_pattern=/tmp/core-%e.%p.%h.%t</code> 将核心转储保存到目录 <code>/tmp</code> 下，并以 <code>core</code> 加上一系列能够标识（出故障的）进程的参数构成的后缀为文件名。</p>`,27)),t("p",null,[e[1]||(e[1]=a("如果你想知道这些形如 ",-1)),e[2]||(e[2]=t("code",null,"%e",-1)),e[3]||(e[3]=a("、",-1)),e[4]||(e[4]=t("code",null,"%p",-1)),e[5]||(e[5]=a(" 的参数都表示什么，请参考 ",-1)),i(s,{href:"http://man7.org/linux/man-pages/man5/core.5.html"},{default:n(()=>[...e[0]||(e[0]=[a("man core",-1)])]),_:1}),e[6]||(e[6]=a("。",-1))]),e[21]||(e[21]=l(`<p>有一点很重要，<code>kernel.core_pattern</code> 是一个全局设置 —— 修改它的时候最好小心一点，因为有可能其它系统功能依赖于把它被设置为一个特定的方式（才能正常工作）。</p><h3 id="kernel-core-pattern-和-ubuntu" tabindex="-1">kernel.core_pattern 和 Ubuntu <a class="header-anchor" href="#kernel-core-pattern-和-ubuntu" aria-label="Permalink to “kernel.core_pattern 和 Ubuntu”">​</a></h3><p>默认情况下在 ubuntu 系统中，<code>kernel.core_pattern</code> 被设置为下面的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sysctl kernel.core_pattern</span></span>
<span class="line"><span>kernel.core_pattern = |/usr/share/apport/apport %p %s %c %d %P</span></span></code></pre></div><p>这引起了我的迷惑（这 apport 是干什么的，它对我的核心转储做了什么？）。以下关于这个我了解到的：</p><ul><li>Ubuntu 使用一种叫做 apport 的系统来报告 apt 包有关的崩溃信息。</li><li>设定 <code>kernel.core_pattern=|/usr/share/apport/apport %p %s %c %d %P</code> 意味着核心转储将被通过管道送给 <code>apport</code> 程序。</li><li>apport 的日志保存在文件 <code>/var/log/apport.log</code> 中。</li><li>apport 默认会忽略来自不属于 Ubuntu 软件包一部分的二进制文件的崩溃信息</li></ul><p>我最终只是跳过了 apport，并把 <code>kernel.core_pattern</code> 重新设置为 <code>sysctl -w kernel.core_pattern=/tmp/core-%e.%p.%h.%t</code>，因为我在一台开发机上，我不在乎 apport 是否工作，我也不想尝试让 apport 把我的核心转储留在磁盘上。</p><h3 id="现在你有了核心转储-接下来干什么" tabindex="-1">现在你有了核心转储，接下来干什么？ <a class="header-anchor" href="#现在你有了核心转储-接下来干什么" aria-label="Permalink to “现在你有了核心转储，接下来干什么？”">​</a></h3><p>好的，现在我们了解了 <code>ulimit</code> 和 <code>kernel.core_pattern</code> ，并且实际上在磁盘的 <code>/tmp</code> 目录中有了一个核心转储文件。太好了！接下来干什么？我们仍然不知道该程序为什么会出现段错误！</p><p>下一步将使用 <code>gdb</code> 打开核心转储文件并获取堆栈调用序列。</p><h3 id="从-gdb-中得到堆栈调用序列" tabindex="-1">从 gdb 中得到堆栈调用序列 <a class="header-anchor" href="#从-gdb-中得到堆栈调用序列" aria-label="Permalink to “从 gdb 中得到堆栈调用序列”">​</a></h3><p>你可以像这样用 <code>gdb</code> 打开一个核心转储文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gdb -c my_core_file</span></span></code></pre></div><p>接下来，我们想知道程序崩溃时的堆栈是什么样的。在 <code>gdb</code> 提示符下运行 <code>bt</code> 会给你一个<ruby>调用序列<rt>backtrace</rt></ruby>。在我的例子里，<code>gdb</code> 没有为二进制文件加载符号信息，所以这些函数名就像 “??????”。幸运的是，（我们通过）加载符号修复了它。</p><p>下面是如何加载调试符号。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>symbol-file /path/to/my/binary</span></span>
<span class="line"><span>sharedlibrary</span></span></code></pre></div><p>这从二进制文件及其引用的任何共享库中加载符号。一旦我这样做了，当我执行 <code>bt</code> 时，gdb 给了我一个带有行号的漂亮的堆栈跟踪！</p><p>如果你想它能工作，二进制文件应该以带有调试符号信息的方式被编译。在试图找出程序崩溃的原因时，堆栈跟踪中的行号非常有帮助。😃</p><h3 id="查看每个线程的堆栈" tabindex="-1">查看每个线程的堆栈 <a class="header-anchor" href="#查看每个线程的堆栈" aria-label="Permalink to “查看每个线程的堆栈”">​</a></h3><p>通过以下方式在 <code>gdb</code> 中获取每个线程的调用栈！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>thread apply all bt full</span></span></code></pre></div><h3 id="gdb-核心转储-惊喜" tabindex="-1">gdb + 核心转储 = 惊喜 <a class="header-anchor" href="#gdb-核心转储-惊喜" aria-label="Permalink to “gdb + 核心转储 = 惊喜”">​</a></h3><p>如果你有一个带调试符号的核心转储以及 <code>gdb</code>，那太棒了！您可以上下查看调用堆栈（LCTT 译注：指跳进调用序列不同的函数中以便于查看局部变量），打印变量，并查看内存来得知发生了什么。这是最好的。</p><p>如果您仍然正在基于 gdb 向导来工作上，只打印出栈跟踪与bt也可以。 😃</p><h3 id="asan" tabindex="-1">ASAN <a class="header-anchor" href="#asan" aria-label="Permalink to “ASAN”">​</a></h3><p>另一种搞清楚您的段错误的方法是使用 AddressSanitizer 选项编译程序（“ASAN”，即 <code>$CC -fsanitize=address</code>）然后运行它。 本文中我不准备讨论那个，因为本文已经相当长了，并且在我的例子中打开 ASAN 后段错误消失了，可能是因为 ASAN 使用了一个不同的内存分配器（系统内存分配器，而不是 tcmalloc）。</p><p>在未来如果我能让 ASAN 工作，我可能会多写点有关它的东西。（LCTT 译注：这里指使用 ASAN 也能复现段错误）</p><h3 id="从一个核心转储得到一个堆栈跟踪真的很亲切" tabindex="-1">从一个核心转储得到一个堆栈跟踪真的很亲切！ <a class="header-anchor" href="#从一个核心转储得到一个堆栈跟踪真的很亲切" aria-label="Permalink to “从一个核心转储得到一个堆栈跟踪真的很亲切！”">​</a></h3><p>这个博客听起来很多，当我做这些的时候很困惑，但说真的，从一个段错误的程序中获得一个堆栈调用序列不需要那么多步骤：</p><ol><li>试试用 <code>valgrind</code></li></ol><p>如果那没用，或者你想要拿到一个核心转储来调查：</p><ol><li>确保二进制文件编译时带有调试符号信息；</li><li>正确的设置 <code>ulimit</code> 和 <code>kernel.core_pattern</code>；</li><li>运行程序；</li><li>一旦你用 <code>gdb</code> 调试核心转储了，加载符号并运行 <code>bt</code>；</li><li>尝试找出发生了什么！</li></ol><p>我可以使用 <code>gdb</code> 弄清楚有个 C++ 的虚表条目指向一些被破坏的内存，这有点帮助，并且使我感觉好像更懂了 C++ 一点。也许有一天我们会更多地讨论如何使用 <code>gdb</code> 来查找问题！</p><hr>`,34)),t("p",null,[e[8]||(e[8]=a("via: ",-1)),i(s,{href:"https://jvns.ca/blog/2018/04/28/debugging-a-segfault-on-linux/"},{default:n(()=>[...e[7]||(e[7]=[a("https://jvns.ca/blog/2018/04/28/debugging-a-segfault-on-linux/",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=a("作者：",-1)),i(s,{href:"https://jvns.ca/about/"},{default:n(()=>[...e[9]||(e[9]=[a("Julia Evans",-1)])]),_:1}),e[13]||(e[13]=a(" 译者：",-1)),i(s,{href:"https://github.com/stephenxs"},{default:n(()=>[...e[10]||(e[10]=[a("stephenxs",-1)])]),_:1}),e[14]||(e[14]=a(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[11]||(e[11]=[a("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=a("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[15]||(e[15]=[a("LCTT",-1)])]),_:1}),e[18]||(e[18]=a(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...e[16]||(e[16]=[a("Linux中国",-1)])]),_:1}),e[19]||(e[19]=a(" 荣誉推出",-1))])])}const C=p(c,[["render",u]]);export{y as __pageData,C as default};
